function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9@.]/g, ''); }
const pipe = $input.all().map(function (i) { return i.json; });
const cfg = $('Read CONFIG').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

function parseDate(v) {
  const t = s(v); if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) { return m[1] + '-' + m[2] + '-' + m[3]; }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (m) { let y = +m[3]; if (y < 100) { y += 2000; } return y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2); }
  const d = new Date(t); return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
function who(p) { const e = s(p.email).split(/[,;\s]+/)[0].toLowerCase(); return e ? e : 'name:' + nz(p.investor); }
const TODAY = '2026-09-10';

// config lines that mention caps, for reference
const capLines = [];
for (const r of cfg) { const line = Object.keys(r).filter(function (k) { return k !== 'row_number'; }).map(function (k) { return s(r[k]); }).filter(Boolean).join(' | ');
  if (/cap|limit|max|lock|per.?day/i.test(line)) { capLines.push(line); } }

// mailbox capacity = the most each owner has actually sent in one day
const ownerDay = {}; const actualWeek = {};
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() !== 'yes') { continue; }
  const d = parseDate(p.date_shared); if (!d) { continue; }
  const k = s(p.owner) + '|' + d; ownerDay[k] = (ownerDay[k] || 0) + 1;
  if (d >= '2026-09-04' && d <= TODAY) { const sn = s(p.startup); actualWeek[sn] = (actualWeek[sn] || 0) + 1; }
}
const ownerCap = {};
for (const k of Object.keys(ownerDay)) { const o = k.split('|')[0]; if (!ownerCap[o] || ownerDay[k] > ownerCap[o]) { ownerCap[o] = ownerDay[k]; } }

// the queue as it stands
const active = {};
for (const r of stRaw) { if (s(r.startup) && s(r.active).toLowerCase() === 'yes') { active[s(r.startup)] = s(r.owner); } }
const rows = [];
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes' || s(p.pause).toLowerCase() === 'yes') { continue; }
  const sn = s(p.startup); if (!active[sn]) { continue; }
  let d = parseDate(p.next_due); if (!d || d <= TODAY) { d = '2026-09-11'; }   // overdue goes out on the next run
  rows.push({ st: sn, owner: s(p.owner), inv: who(p), due: d, pri: parseFloat(s(p.priority)) || 0 });
}
rows.sort(function (a, b) { return a.due < b.due ? -1 : (a.due > b.due ? 1 : b.pri - a.pri); });

// weekdays from tomorrow, grouped into 5-weekday weeks
const days = []; { const d = new Date(Date.UTC(2026, 8, 11)); while (days.length < 400) { const w = d.getUTCDay(); if (w !== 0 && w !== 6) { days.push(d.toISOString().slice(0, 10)); } d.setUTCDate(d.getUTCDate() + 1); } }

function simulate(invCap, perDay) {
  let remaining = rows.slice(); const byStartup = {}; const weekTotals = []; let deferredEver = 0; const drain = {};
  let invWeek = {};
  for (let di = 0; di < days.length && remaining.length; di++) {
    const day = days[di]; const wk = Math.floor(di / 5);
    if (di % 5 === 0) { invWeek = {}; }
    const ownerToday = {}; const invToday = {};
    const next = [];
    for (const r of remaining) {
      if (r.due > day) { next.push(r); continue; }
      const oc = ownerCap[r.owner] || 40;
      if ((ownerToday[r.owner] || 0) >= oc) { next.push(r); continue; }
      const used = perDay ? (invToday[r.inv] || 0) : (invWeek[r.inv] || 0);
      if (invCap && used >= invCap) { if (!r.bumped) { r.bumped = true; deferredEver++; } next.push(r); continue; }
      ownerToday[r.owner] = (ownerToday[r.owner] || 0) + 1;
      invToday[r.inv] = (invToday[r.inv] || 0) + 1; invWeek[r.inv] = (invWeek[r.inv] || 0) + 1;
      if (!byStartup[r.st]) { byStartup[r.st] = []; }
      byStartup[r.st][wk] = (byStartup[r.st][wk] || 0) + 1;
      weekTotals[wk] = (weekTotals[wk] || 0) + 1;
      drain[r.st] = wk + 1;
    }
    remaining = next;
    for (const r of remaining) { delete r.bumped; }
  }
  return { byStartup: byStartup, weekTotals: weekTotals, deferred: deferredEver, drain: drain, leftover: remaining.length };
}
// each scenario gets fresh copies (simulate mutates only the bumped flag, which it clears)
const base = simulate(0, false);
const wk5 = simulate(5, false);
const day5 = simulate(5, true);

function w(arr, i) { return (arr && arr[i]) || 0; }
function avg4(arr) { let t = 0; for (let i = 0; i < 4; i++) { t += w(arr, i); } return Math.round(t / 4 * 10) / 10; }
const per = [];
for (const sn of Object.keys(active)) {
  const q = rows.filter(function (r) { return r.st === sn; }).length;
  per.push({ startup: sn, owner: active[sn], queued: q, actual_last_week: actualWeek[sn] || 0,
    nocap_w1_4: [w(base.byStartup[sn], 0), w(base.byStartup[sn], 1), w(base.byStartup[sn], 2), w(base.byStartup[sn], 3)],
    nocap_avg: avg4(base.byStartup[sn]), nocap_weeks_to_empty: base.drain[sn] || 0,
    cap5wk_w1_4: [w(wk5.byStartup[sn], 0), w(wk5.byStartup[sn], 1), w(wk5.byStartup[sn], 2), w(wk5.byStartup[sn], 3)],
    cap5wk_avg: avg4(wk5.byStartup[sn]), cap5wk_weeks_to_empty: wk5.drain[sn] || 0,
    cap5day_avg: avg4(day5.byStartup[sn]) });
}
per.sort(function (a, b) { return b.cap5wk_avg - a.cap5wk_avg || a.startup.localeCompare(b.startup); });
function totals(sim) { const t = []; for (let i = 0; i < 8; i++) { t.push(w(sim.weekTotals, i)); } return t; }
return [{ json: {
  queued_rows: rows.length, active_startups: Object.keys(active).length,
  mailbox_daily_capacity_used: ownerCap, config_cap_lines: capLines,
  weekly_totals_first8: { nocap: totals(base), cap5_per_week: totals(wk5), cap5_per_day: totals(day5) },
  deals_pushed_to_later_week_by_cap: { cap5_per_week: wk5.deferred, cap5_per_day: day5.deferred },
  weeks_to_send_whole_queue: { nocap: base.weekTotals.length, cap5_per_week: wk5.weekTotals.length, cap5_per_day: day5.weekTotals.length },
  per_startup: per } }];
